    public final String s(String str) {
        return "package " + str + ";\n\nimport android.Manifest;\nimport android.content.pm.PackageManager;\nimport android.os.Bundle;\nimport android.view.View;\nimport android.widget.TextView;\n\nimport androidx.appcompat.app.AppCompatActivity;\nimport androidx.core.app.ActivityCompat;\nimport androidx.core.content.ContextCompat;\n\n// 运行时权限：检查 + 申请 + 回调，验证清单声明 + 动态授权流程。\npublic class PermissionActivity extends AppCompatActivity {\n\n    private TextView status;\n\n    @Override\n    protected void onCreate(Bundle savedInstanceState) {\n        super.onCreate(savedInstanceState);\n        setContentView(R.layout.activity_permission);\n\n        status = findViewById(R.id.perm_status);\n        bind(R.id.btn_camera, Manifest.permission.CAMERA, 1);\n        bind(R.id.btn_location, Manifest.permission.ACCESS_FINE_LOCATION, 2);\n        // POST_NOTIFICATIONS 用字符串字面量，兼容较低 android.jar stub。\n        bind(R.id.btn_notify, \"android.permission.POST_NOTIFICATIONS\", 3);\n    }\n\n    private void bind(int viewId, final String permission, final int requestCode) {\n        findViewById(viewId).setOnClickListener(new View.OnClickListener() {\n            @Override\n            public void onClick(View v) {\n                if (ContextCompat.checkSelfPermission(PermissionActivity.this, permission)\n                        == PackageManager.PERMISSION_GRANTED) {\n                    status.setText(permission + \" 已授权\");\n                } else {\n                    ActivityCompat.requestPermissions(\n                            PermissionActivity.this, new String[]{permission}, requestCode);\n                }\n            }\n        });\n    }\n\n    @Override\n    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {\n        super.onRequestPermissionsResult(requestCode, permissions, grantResults);\n        boolean granted = grantResults.length > 0\n                && grantResults[0] == PackageManager.PERMISSION_GRANTED;\n        String name = permissions.length > 0 ? permissions[0] : \"\";\n        status.setText(name + (granted ? \" 已授权\" : \" 被拒绝\"));\n    }\n}\n";
    }

